<?php
$ROOT='../'; define('DVWA_WEB_PAGE_TO_ROOT','../');
require_once DVWA_WEB_PAGE_TO_ROOT.'dvwa/includes/dvwaPage.inc.php'; dvwaPageStartup(['authenticated']); dvwaDatabaseConnect(); dvwaSecurityEnsureSchema(); require_once __DIR__.'/_intel_common.php';
$id=max(0,(int)($_GET['id']??0));$e=null;if($id){$r=siQ('SELECT id,event_time,attack_type,target,source_ip,result,reason FROM security_events WHERE id='.$id.' LIMIT 1');$e=$r[0]??null;}
$body=siShell('SOC / INCIDENT INVESTIGATION','مركز العمليات / التحقيق','Event Investigation','تحقيق الحدث','Inspect one recorded laboratory event with secrets and full payloads excluded.','افحص حدثًا مختبريًا مسجلًا مع استبعاد الأسرار وحمولات الهجوم الكاملة.','red');
if(!$e){$body.='<section class="si-panel not-found">'.siHeader('EVENT STATUS','حالة الحدث','NOT FOUND','غير موجود').'<div class="not-found-copy"><b>'.siE(siText('Event record not found.','لم يتم العثور على سجل الحدث.')).'</b><p>'.siE(siText('Return to the dashboard and open a recorded event from the security stream.','ارجع إلى لوحة المراقبة وافتح حدثًا مسجلًا من تدفق الأحداث الأمنية.')).'</p>'.siBtn('BACK TO COMMAND CENTER','العودة إلى مركز القيادة','dashboard.php').'</div></section>';}else{$blocked=$e['result']==='Blocked';$body.='<div class="investigation-grid"><section class="si-panel event-detail"><header><span>'.siE(siText('EVENT','الحدث')).'</span><b>#'.(int)$e['id'].'</b></header><div class="investigation-title"><div class="investigation-status '.($blocked?'blocked':'danger').'">'.($blocked?'✓':'!').'</div><div><h2>'.siE(siAttackLabel($e['attack_type'])).'</h2><span>'.siE($e['event_time']).'</span></div><b>'.siE($blocked?siText('BLOCKED','محجوب'):siText('SUCCESSFUL','ناجح')).'</b></div><dl class="facts"><div><dt>'.siE(siText('TARGET','الهدف')).'</dt><dd>'.siE($e['target']).'</dd></div><div><dt>'.siE(siText('SOURCE IP','عنوان المصدر')).'</dt><dd>'.siE($e['source_ip']?:'N/A').'</dd></div><div><dt>'.siE(siText('REASON','السبب')).'</dt><dd>'.siE($e['reason']?:siText('Not recorded','لم يتم تسجيل سبب')).'</dd></div></dl></section><section class="si-panel"><header><span>'.siE(siText('INVESTIGATION PATH','مسار التحقيق')).'</span><b>'.siE(siText('LOCAL LAB','مختبر محلي')).'</b></header><div class="investigation-flow"><div><i>01</i><b>'.siE(siText('DETECT','اكتشاف')).'</b></div><em></em><div><i>02</i><b>'.siE(siText('LOG','تسجيل')).'</b></div><em></em><div><i>03</i><b>'.siE(siText('ASSESS','تقييم')).'</b></div><em></em><div><i>04</i><b>'.siE(siText('RETEST','إعادة اختبار')).'</b></div></div><p class="investigation-note">'.siE($blocked?siText('The defensive control recorded this attempt as blocked.','سجل الضابط الدفاعي هذه المحاولة كمحجوبة.'):siText('The telemetry recorded a successful laboratory path. Review and retest the associated protection.','سجلت المراقبة مسارًا ناجحًا داخل المختبر. راجع الحماية المرتبطة وأعد الاختبار.')).'</p></section></div><div class="investigation-actions">'.siBtn('COMMAND CENTER','مركز القيادة','dashboard.php').siBtn('THREAT TIMELINE','الخط الزمني','timeline.php').siBtn('SECURITY REPORT','التقرير الأمني','report.php').'</div>';}
siBase('Event Investigation','تحقيق الحدث',$body,'security_investigation');
